%%Papildomas 3LD, EGureckas
%13 var
clearvars
close all
clc

A = 7;
f = 4;
sigma = 2;

U1 = 4.5;
U2 = 2.5;

t = 0:0.005:1;

s = A*sin(2*pi*f*t);
n = sigma*randn(size(t));
sn = s+n;

sf = sn;
sf(abs(sf) < U2) = 0;

ind = sn > U1;
t1 = t(ind);
s1 = sn(ind);

min_ind = s1 == min(s1);
max_ind = s1 == max(s1);

figure('Position',[100 100 1200 450]) %[output:7be37e27]

subplot(1,2,1) %[output:7be37e27]

h1 = plot(t,sn,'-','LineWidth',1.75); %[output:7be37e27]
hold on %[output:7be37e27]
h2 = plot(t,sf,'--','LineWidth',1.75); %[output:7be37e27]
h3 = yline(U1,'r','LineWidth',1.5); %[output:7be37e27]
h4 = yline(U2,'k','LineWidth',1.5); %[output:7be37e27]
hold off %[output:7be37e27]

xlabel('Laikas, t (s)') %[output:7be37e27]
ylabel('Įtampa, U (V)') %[output:7be37e27]
title('Pradinis ir filtruotas signalai', ... %[output:7be37e27]
    'Color',[0.4940 0.1840 0.5560], ... %[output:7be37e27]
    'FontSize',11) %[output:7be37e27]

legend([h1 h2 h3 h4], ... %[output:7be37e27]
    'Pradinis signalas', ... %[output:7be37e27]
    'Filtruotas signalas', ... %[output:7be37e27]
    'U_1', ... %[output:7be37e27]
    'U_2', ... %[output:7be37e27]
    'Location','best') %[output:7be37e27]

grid on %[output:7be37e27]
xlim([min(t) max(t)]) %[output:7be37e27]
ylim([min([sn sf])-1 max([sn sf])+1]) %[output:7be37e27]


subplot(1,2,2) %[output:7be37e27]

h5 = stem(t1,s1,'LineWidth',1.75); %[output:7be37e27]
hold on %[output:7be37e27]

h6 = plot(t1(min_ind),s1(min_ind),'ko', ... %[output:7be37e27]
    'MarkerSize',8, ... %[output:7be37e27]
    'LineWidth',1.5); %[output:7be37e27]

h7 = plot(t1(max_ind),s1(max_ind),'go', ... %[output:7be37e27]
    'MarkerSize',8, ... %[output:7be37e27]
    'LineWidth',1.5); %[output:7be37e27]

hold off %[output:7be37e27]

xlabel('Laikas, t (s)') %[output:7be37e27]
ylabel('Įtampa, U (V)') %[output:7be37e27]
title('Pradinio signalo reikšmės virš U_1', ... %[output:7be37e27]
    'Color',[0.4940 0.1840 0.5560], ... %[output:7be37e27]
    'FontSize',11) %[output:7be37e27]

legend([h5 h6 h7], ... %[output:7be37e27]
    'U > U_1', ... %[output:7be37e27]
    'Minimali reikšmė', ... %[output:7be37e27]
    'Maksimali reikšmė', ... %[output:7be37e27]
    'Location','best') %[output:7be37e27]

grid on %[output:7be37e27]
xlim([min(t) max(t)]) %[output:7be37e27]
ylim([min(s1)-1 max(s1)+1]) %[output:7be37e27]

